attribute checkpointsSatisfied : Boolean = stage.exitCheckpoints->forAll { in checkpoint : Checkpoint;
                currentAssessments->exists { in assessment : CheckpointAssessment;
                    assessment.checkpoint == checkpoint and
                    assessment.outcome == CheckpointOutcome::passed and
                    assessment.evaluatedRevision == artifactRevision
                }
            }

attribute subFlowSatisfied : Boolean = size(stage.subFlow) == 0 or
            subFlowExecution->exists { in execution : FlowExecution;
                execution.assignedFlow == stage.subFlow and
                execution.status == FlowStatus::completed
            }

attribute passedGates : Integer = size(visit.stage.exitCheckpoints->select {
            in gate : Checkpoint;
            visit.currentAssessments->exists { in assessment : CheckpointAssessment;
                assessment.checkpoint == gate and
                assessment.outcome == CheckpointOutcome::passed and
                assessment.evaluatedRevision == visit.artifactRevision
            }
        })

attribute passedGates : Integer = size(visit.stage.exitCheckpoints->select {
            in gate : Checkpoint;
            visit.currentAssessments->exists { in assessment : CheckpointAssessment;
                assessment.checkpoint == gate and
                assessment.outcome == CheckpointOutcome::passed and
                assessment.evaluatedRevision == visit.artifactRevision
            }
        })
